name: Release

on:
  push:
    tags: ["v*.*.*"]

permissions:
  contents: write
  id-token: write
  attestations: write

jobs:
  package:
    runs-on: ubuntu-22.04
    permissions:
      contents: write
      id-token: write
      attestations: write
    env:
      NEXUS_BUILD_CONTAINER_IMAGE: rust:1.95.0-bookworm@sha256:4c2fd73ef19c5ef9d54bee03b06b2839a392604fbfcd578ed948b71b37c1d7fb
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0
      - run: sudo apt-get update
      - run: sudo apt-get install --yes acl make bubblewrap build-essential meson ninja-build pkg-config libcap-dev
      - uses: actions/setup-go@b7ad1dad31e06c5925ef5d2fc7ad053ef454303e # v7.0.0
        with:
          go-version: '1.22.12'
      - name: Install pinned evaluator toolchains
        run: bash scripts/install-evaluator-toolchains.sh
      - run: bash scripts/ensure-ci-bubblewrap.sh
      - run: bash scripts/ensure-ci-user-cgroups.sh
      - name: Mount a dedicated capped tmpfs for evaluator resource fixtures
        run: |
          root=/mnt/nexus-eval-release
          sudo install -d -o "$USER" -g "$USER" -m 0711 "$root"
          sudo mount -t tmpfs -o size=128m,mode=0711,uid="$(id -u)",gid="$(id -g)" nexus-eval-release "$root"
          echo "NEXUS_EVAL_TEST_WORKSPACE_ROOT=$root" >> "$GITHUB_ENV"
          runtime_root=/opt/nexus-eval-ci-runtime
          sudo install -d -o "$USER" -g "$USER" -m 0711 "$runtime_root"
          echo "NEXUS_EVAL_TEST_RUNTIME_ROOT=$runtime_root" >> "$GITHUB_ENV"
      - uses: dtolnay/rust-toolchain@b725eda525362e7cf34af9a7243cac1e3f01a7ec # stable
      - name: Install cargo tools (audit, deny, about, cyclonedx)
        run: |
          CARGO_HOME="${CARGO_HOME:-$HOME/.cargo}"
          export CARGO_HOME
          mkdir -p "$CARGO_HOME/bin"
          echo "$CARGO_HOME/bin" >> "$GITHUB_PATH"
          export PATH="$CARGO_HOME/bin:$PATH"
          cargo install cargo-audit --locked --version 0.22.2
          curl -fsSL https://github.com/EmbarkStudios/cargo-deny/releases/download/0.20.2/cargo-deny-0.20.2-x86_64-unknown-linux-musl.tar.gz | tar -xz -C "$RUNNER_TEMP"
          mv "$RUNNER_TEMP/cargo-deny-0.20.2-x86_64-unknown-linux-musl/cargo-deny" "$CARGO_HOME/bin/"
          curl -fsSL https://github.com/EmbarkStudios/cargo-about/releases/download/0.9.2/cargo-about-0.9.2-x86_64-unknown-linux-musl.tar.gz | tar -xz -C "$RUNNER_TEMP"
          mv "$RUNNER_TEMP/cargo-about-0.9.2-x86_64-unknown-linux-musl/cargo-about" "$CARGO_HOME/bin/"
          curl -fsSL https://github.com/CycloneDX/cyclonedx-rust-cargo/releases/download/cargo-cyclonedx-0.5.9/cargo-cyclonedx-x86_64-unknown-linux-musl.tar.xz | tar -xJ -C "$RUNNER_TEMP"
          mv "$RUNNER_TEMP/cargo-cyclonedx-x86_64-unknown-linux-musl/cargo-cyclonedx" "$CARGO_HOME/bin/"
          curl -fsSL https://github.com/CycloneDX/cyclonedx-cli/releases/download/v0.33.1/cyclonedx-linux-x64 -o "$CARGO_HOME/bin/cyclonedx"
          chmod +x "$CARGO_HOME/bin/cyclonedx"
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 22.22.1
          cache: npm
          cache-dependency-path: cli/package-lock.json
      - name: Require the pinned release Node and npm versions
        run: |
          test "$(node --version)" = "v22.22.1"
          test "$(npm --version)" = "10.9.4"
      - name: Install selected Node runtime for isolated evaluation commands
        run: |
          node_runtime="$(readlink -f "$(command -v node)")"
          npm_cli="$(readlink -f "$(command -v npm)")"
          npm_root="$(dirname "$(dirname "$npm_cli")")"
          case "$npm_root" in */lib/node_modules/npm) ;; *) echo "Unexpected setup-node npm package path" >&2; exit 1 ;; esac
          test -f "$npm_root/package.json"
          sudo install -o root -g root -m 0755 "$node_runtime" /usr/bin/node
          sudo install -d -o root -g root -m 0755 /usr/lib/nexus-ci/npm
          sudo cp -a "$npm_root/." /usr/lib/nexus-ci/npm/
          sudo chown -hR root:root /usr/lib/nexus-ci/npm
          sudo chmod 0755 /usr/lib/nexus-ci/npm/bin/npm-cli.js
          sudo ln -sfn /usr/lib/nexus-ci/npm/bin/npm-cli.js /usr/bin/npm
          test "$(/usr/bin/node --version)" = "$(node --version)"
          test "$(env PATH=/usr/bin:/bin /usr/bin/npm --version)" = "$(npm --version)"
      - name: Require a version-matched tag on main
        run: |
          git fetch origin main --no-tags
          git merge-base --is-ancestor "$GITHUB_SHA" origin/main
          test "${GITHUB_REF_NAME#v}" = "$(node -p 'require("./package.json").version')"
          node scripts/sync-version.mjs --check --tag "$GITHUB_REF_NAME"
          test -f "docs/releases/${GITHUB_REF_NAME}.md" || { echo "Missing docs/releases/${GITHUB_REF_NAME}.md" >&2; exit 1; }
      - name: Require a stable tag to be a version-only commit on its RC
        if: ${{ !contains(github.ref_name, '-') }}
        # The checkout has full history and tags (fetch-depth: 0). The checker runs from the RC's own copy so a stable
        # commit cannot replace it; branch and tag protection remain the control over the workflow file itself.
        run: |
          rc="$(git tag --points-at "$GITHUB_SHA^" | grep -E "^${GITHUB_REF_NAME//./\\.}-rc\.[0-9]+$" | sort -V | tail -n 1 || true)"
          test -n "$rc" || { echo "the parent of $GITHUB_REF_NAME is not a ${GITHUB_REF_NAME}-rc.N tag" >&2; exit 1; }
          git show "$rc:scripts/check-version-only-diff.mjs" > "$RUNNER_TEMP/check-version-only-diff.mjs"
          node "$RUNNER_TEMP/check-version-only-diff.mjs" "$rc" "$GITHUB_SHA"
      - run: npm ci --prefix cli
      - run: npm --prefix cli run build
      - run: cargo test --locked --manifest-path core/Cargo.toml
      - run: cargo build --locked --release --manifest-path core/Cargo.toml --bin harness-core --bin nexus-tui
      - name: Run the CLI suite with a hang bound
        # Normal runs take 12-20 minutes; a test process that never exits must fail the job, not hold it for 6 hours.
        timeout-minutes: 45
        run: npm --prefix cli test
      - run: bash scripts/security_gates.sh
      - run: bash scripts/package-linux.sh "$GITHUB_REF_NAME" "$RUNNER_TEMP/dist"
      - run: bash scripts/package-linux.sh "$GITHUB_REF_NAME" "$RUNNER_TEMP/repro-check"
      - run: cmp "$RUNNER_TEMP/dist/nexus-linux-x86_64-$GITHUB_REF_NAME.tar.gz" "$RUNNER_TEMP/repro-check/nexus-linux-x86_64-$GITHUB_REF_NAME.tar.gz"
      - run: cmp "$RUNNER_TEMP/dist/SHA256SUMS" "$RUNNER_TEMP/repro-check/SHA256SUMS"
      - run: cmp "$RUNNER_TEMP/dist/THIRD_PARTY_NOTICES.txt" "$RUNNER_TEMP/repro-check/THIRD_PARTY_NOTICES.txt"
      - run: cyclonedx validate --input-file "$RUNNER_TEMP/dist/sbom.cdx.json" --fail-on-errors
      - run: cmp "$RUNNER_TEMP/dist/sbom.cdx.json" "$RUNNER_TEMP/repro-check/sbom.cdx.json"
      - run: cmp "$RUNNER_TEMP/dist/install.sh" "$RUNNER_TEMP/repro-check/install.sh"
      - run: bash scripts/smoke-package.sh "$RUNNER_TEMP/dist/nexus-linux-x86_64-$GITHUB_REF_NAME.tar.gz"
      - run: bash scripts/installer-smoke.sh "$GITHUB_WORKSPACE/install.sh" "$RUNNER_TEMP/dist/nexus-linux-x86_64-$GITHUB_REF_NAME.tar.gz"
      - name: Attest build provenance
        uses: actions/attest-build-provenance@4d101475d8b20a2381f78447822ac1eab6504dd8 # v4.2.2
        with:
          subject-path: |
            ${{ runner.temp }}/dist/nexus-linux-x86_64-${{ github.ref_name }}.tar.gz
            ${{ runner.temp }}/dist/SHA256SUMS
      # RC tags (vX.Y.Z-rc.N) publish a prerelease: the workflow-produced RC is the qualification candidate
      # (ACCEPTANCE §1.1 stage 2). Stable tags only build an unpublished draft (stage 5); it is published by hand with
      # `gh release edit <tag> --draft=false` after the stable artifact checks and the signed acceptance disposition.
      - uses: softprops/action-gh-release@8a0cd651e5b2365bd640854a3fa5dfc70e4875f3 # v3.0.4
        with:
          files: ${{ runner.temp }}/dist/*
          body_path: docs/releases/${{ github.ref_name }}.md
          prerelease: ${{ contains(github.ref_name, '-') }}
          draft: ${{ !contains(github.ref_name, '-') }}
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

// The release job runs the same CLI suite as CI, including evaluator tests that need the
// pinned toolchains and sandbox. rc.12's release failed with "go: command not found"
// because release.yml lacked steps that ci.yml had; keep the two environments aligned.
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const read = (name: string) => fs.readFileSync(path.join(root, ".github/workflows", name), "utf8");

const REQUIRED_EVALUATOR_SETUP = [
  "go-version: '1.22.12'",
  "run: bash scripts/install-evaluator-toolchains.sh",
  "run: bash scripts/ensure-ci-bubblewrap.sh",
  "run: bash scripts/ensure-ci-user-cgroups.sh",
  'echo "NEXUS_EVAL_TEST_WORKSPACE_ROOT=$root" >> "$GITHUB_ENV"',
  'echo "NEXUS_EVAL_TEST_RUNTIME_ROOT=$runtime_root" >> "$GITHUB_ENV"',
  "sudo install -o root -g root -m 0755 \"$node_runtime\" /usr/bin/node",
];
const RETIRED_RUNNER_TRIM_STEP = "bash scripts/ci-trim-runner-image.sh";

function jobSection(workflow: string, name: string): string {
  const marker = `\n  ${name}:`;
  const start = workflow.indexOf(marker);
  assert.notEqual(start, -1, `workflow defines the ${name} job`);
  const bodyStart = start + marker.length;
  const remaining = workflow.slice(bodyStart);
  const nextJob = remaining.search(/\n  [a-zA-Z0-9_-]+:/);
  return nextJob === -1 ? remaining : remaining.slice(0, nextJob);
}

// A job that runs the whole suite in one step (`npm --prefix cli test`), and CI's shard leg, which runs one
// shard of the same suite (`npm run test:cli -- --shard=K/N`). The suite step of each needs the same environment.
const WHOLE_SUITE = "run: npm --prefix cli test";
const SHARD_SUITE = /npm --prefix cli run test:cli -- --shard=\$\{\{ matrix\.shard \}\}\/(\d+) /;

function suiteStep(job: string, jobName: string): { position: number; timeoutMinutes: number } {
  const whole = job.indexOf(WHOLE_SUITE);
  const shard = SHARD_SUITE.exec(job);
  assert.ok(whole >= 0 || shard, `${jobName} runs the CLI suite`);
  const position = whole >= 0 ? whole : shard!.index;
  // The step-level bound is the last `timeout-minutes` before the command, inside the same step.
  const stepStart = job.lastIndexOf("\n      - ", position);
  const bound = /^ {8}timeout-minutes: (\d+)$/m.exec(job.slice(stepStart, position));
  assert.ok(bound, `${jobName} bounds the CLI suite step so a hung test process fails the job`);
  return { position, timeoutMinutes: Number(bound[1]) };
}

test("every job that runs the CLI suite prepares the same evaluator environment first and bounds the suite step", () => {
  const ci = read("ci.yml");
  const release = read("release.yml");
  const jobs = [
    ["CI shard leg", jobSection(ci, "test-shard"), "shard"],
    ["CI Linux packaging", jobSection(ci, "linux-x86_64"), "whole"],
    ["release package", jobSection(release, "package"), "whole"],
  ] as const;

  for (const [jobName, job, kind] of jobs) {
    assert.ok(
      !job.includes(RETIRED_RUNNER_TRIM_STEP),
      `${jobName} does not invoke the retired runner trim script`,
    );
    assert.equal(job.includes(WHOLE_SUITE), kind === "whole", `${jobName} runs the ${kind === "whole" ? "whole suite in one step" : "suite by shard"}`);
    const suite = suiteStep(job, jobName);
    if (kind === "whole") assert.equal(suite.timeoutMinutes, 45, `${jobName} bounds the whole suite to 45 minutes`);
    else assert.ok(suite.timeoutMinutes <= 45, `${jobName} bounds a shard no more loosely than the whole suite`);
    const positions = REQUIRED_EVALUATOR_SETUP.map((step) => {
      const position = job.indexOf(step);
      assert.ok(position >= 0, `${jobName} includes required evaluator setup: ${step}`);
      assert.ok(position < suite.position, `${jobName} runs evaluator setup before the CLI suite: ${step}`);
      return position;
    });
    for (let index = 1; index < positions.length; index += 1) {
      assert.ok(positions[index - 1] < positions[index], `${jobName} preserves evaluator setup order`);
    }
  }
});

test("the CI shard legs and the gates job together run what `npm --prefix cli test` runs, on both Node versions", () => {
  // release.yml runs `npm --prefix cli test`. CI's test-matrix checks must stand for the same commands.
  const scripts = JSON.parse(fs.readFileSync(path.join(root, "cli/package.json"), "utf8")).scripts;
  assert.equal(scripts.test, "npm run test:cli && npm run test:scope", "the suite is exactly test:cli then test:scope");
  assert.equal(scripts["test:cli"], "node scripts/test_shards.mjs", "test:cli is the sharding runner, which runs every file when no shard is named");

  const ci = read("ci.yml");
  const shard = jobSection(ci, "test-shard");
  const gates = jobSection(ci, "test-gates");
  const nodes = /^ {8}node: \[22, 24\]$/m;
  assert.match(shard, nodes, "shard legs run on Node 22 and 24");
  assert.match(gates, nodes, "the gates run on Node 22 and 24");
  assert.match(shard, /^ {6}fail-fast: false/m, "one failing leg does not cancel the others");

  // The matrix must list every index 1..N of the N in --shard=K/N, or part of the suite would never run.
  const total = Number(SHARD_SUITE.exec(shard)?.[1]);
  const listed = /^ {8}shard: \[([\d, ]+)\]$/m.exec(shard)?.[1].split(",").map((value) => Number(value.trim()));
  assert.deepEqual(listed, Array.from({ length: total }, (_, index) => index + 1), `the shard matrix is exactly 1..${total}`);
  // The suite's exit status must survive the pipe into the log file.
  const suiteRun = shard.slice(shard.lastIndexOf("\n      - ", SHARD_SUITE.exec(shard)!.index));
  assert.match(suiteRun, /set -o pipefail\n[\s\S]*\| tee /, "the shard step fails when the suite fails although its output is piped");
  for (const [jobName, job] of [["test-shard", shard], ["test-gates", gates]] as const) {
    assert.doesNotMatch(job, /continue-on-error|^ {4}if:/m, `${jobName} is never skipped and cannot fail softly`);
  }

  assert.match(gates, /^ {8}run: npm --prefix cli run test:scope$/m, "the gates job runs the other half of the suite");
  for (const gate of [
    "- run: node scripts/sync-version.mjs --check",
    "- run: node scripts/check_doc_versions.mjs",
    "- run: node scripts/check_requirements.mjs --enforce",
    "- run: node scripts/check_invariants.mjs",
    'node scripts/check_deprecated_lock.mjs "$lockfile"',
    "make lint",
    "- run: cargo test --locked --manifest-path core/Cargo.toml",
  ]) assert.ok(gates.includes(gate), `the gates job still runs: ${gate}`);
  assert.ok(shard.includes("- run: cargo build --locked --release --manifest-path core/Cargo.toml --bin harness-core --bin nexus-tui"), "every leg builds the release core the suite drives");
});

test("the required test-matrix checks fail unless every gate and every shard leg succeeded", () => {
  const ci = read("ci.yml");
  const aggregate = jobSection(ci, "test-matrix");
  // Check names `test-matrix (22)` and `test-matrix (24)` come from the job id and this matrix; a `name:` would change them.
  assert.match(aggregate, /^ {8}node: \[22, 24\]$/m);
  assert.doesNotMatch(aggregate, /^ {4}name:/m);
  assert.match(aggregate, /^ {4}needs: \[test-gates, test-shard\]$/m);
  // A skipped required check counts as passing, so the job must run whatever happened to the jobs it needs.
  assert.match(aggregate, /^ {4}if: \$\{\{ always\(\) \}\}$/m);
  assert.doesNotMatch(aggregate, /continue-on-error/);
  assert.match(aggregate, /GATES_RESULT: \$\{\{ needs\.test-gates\.result \}\}/);
  assert.match(aggregate, /SHARDS_RESULT: \$\{\{ needs\.test-shard\.result \}\}/);
  assert.match(aggregate, /^ {10}test "\$GATES_RESULT" = success$/m);
  assert.match(aggregate, /^ {10}test "\$SHARDS_RESULT" = success$/m);
  assert.match(ci, /^ {2}linux-x86_64:$/m, "the packaging check keeps its name");
});

test("superseded pull-request runs are cancelled, push runs never are, and every CI job has a timeout", () => {
  const ci = read("ci.yml");
  assert.match(ci, /^concurrency:\n {2}group: ci-\$\{\{ github\.event_name == 'pull_request' && format\('pr-\{0\}', github\.event\.pull_request\.number\) \|\| format\('run-\{0\}', github\.run_id\) \}\}\n {2}cancel-in-progress: \$\{\{ github\.event_name == 'pull_request' \}\}$/m);
  const names = [...ci.slice(ci.indexOf("\njobs:")).matchAll(/^ {2}([a-zA-Z0-9_-]+):$/gm)].map((match) => match[1]);
  assert.deepEqual(names, ["test-gates", "test-shard", "test-matrix", "linux-x86_64", "diff-coverage"]);
  for (const name of names) assert.match(jobSection(ci, name), /^ {4}timeout-minutes: \d+$/m, `${name} has a job timeout`);
  const checkouts = ci.match(/uses: actions\/checkout@[0-9a-f]{40} # v[\d.]+\n {8}with:\n {10}fetch-depth: 0.*\n {10}persist-credentials: false/g) ?? [];
  assert.equal(checkouts.length, (ci.match(/uses: actions\/checkout@/g) ?? []).length, "no checkout leaves the token in the clone");
});
export PATH := $(HOME)/.cargo/bin:$(PATH)
APPROVED_RUST_BUILD_IMAGE := rust:1.95.0-bookworm@sha256:4c2fd73ef19c5ef9d54bee03b06b2839a392604fbfcd578ed948b71b37c1d7fb

.PHONY: all setup build build-core build-cli check clean lint typecheck fmt-check test test-ci test-fixture-notice test-durations-merge audit security-scan sbom verify-reproducibility

all: build

setup:
	npm --prefix cli install
	cargo build --release --manifest-path core/Cargo.toml
	npm --prefix cli run build

build: build-core build-cli

build-core:
	cargo build --release --manifest-path core/Cargo.toml

build-cli:
	npm --prefix cli run build

check:
	node cli/dist/index.js check

# PR-required static gates. rustfmt is diff-scoped (scripts/check_fmt.sh) because the core has legacy drift.
lint: typecheck
	cargo clippy --locked --manifest-path core/Cargo.toml --all-targets -- -D warnings
	$(MAKE) fmt-check

typecheck:
	npm --prefix cli run typecheck

fmt-check:
	bash scripts/check_fmt.sh

clean:
	cargo clean --manifest-path core/Cargo.toml
	rm -rf dist cli/dist cli/node_modules

audit:
	npm --prefix cli audit

security-scan:
	bash scripts/security_gates.sh

sbom:
	bash scripts/generate_sbom.sh

verify-reproducibility:
	@echo "[*] Verifying reproducible package build..."
	@TMP1=$$(mktemp -d) && TMP2=$$(mktemp -d) && \
	VERSION=$$(node -p 'require("./package.json").version') && \
	NEXUS_BUILD_CONTAINER_IMAGE=$(APPROVED_RUST_BUILD_IMAGE) bash scripts/package-linux.sh "v$$VERSION" "$$TMP1" && \
	NEXUS_BUILD_CONTAINER_IMAGE=$(APPROVED_RUST_BUILD_IMAGE) bash scripts/package-linux.sh "v$$VERSION" "$$TMP2" && \
	cmp "$$TMP1/nexus-linux-x86_64-v$$VERSION.tar.gz" "$$TMP2/nexus-linux-x86_64-v$$VERSION.tar.gz" && \
	cmp "$$TMP1/SHA256SUMS" "$$TMP2/SHA256SUMS" && \
	cmp "$$TMP1/THIRD_PARTY_NOTICES.txt" "$$TMP2/THIRD_PARTY_NOTICES.txt" && \
	cmp "$$TMP1/sbom.cdx.json" "$$TMP2/sbom.cdx.json" && \
	cmp "$$TMP1/install.sh" "$$TMP2/install.sh" && \
	rm -rf "$$TMP1" "$$TMP2"
	@echo "[+] Reproducible build verification succeeded (byte-identical artifacts)."

# `make test` runs every gate and fails at the end, so a CLI failure does not hide the terminal-scope or
# security result. It calls the two halves of `npm --prefix cli test` by name (test:cli, test:scope), so the
# step list lives only in cli/package.json.
# CI evaluator fixtures (tmpfs workspace and runtime root) come from `make test-ci`; see docs/DEVELOPMENT.md.
test: test-fixture-notice
	@rc=0; \
	cargo test --manifest-path core/Cargo.toml || { echo "[!] FAILED: cargo test"; rc=1; }; \
	npm --prefix cli run test:cli || { echo "[!] FAILED: CLI suite"; rc=1; }; \
	npm --prefix cli run test:scope || { echo "[!] FAILED: terminal scope"; rc=1; }; \
	bash scripts/security_gates.sh || { echo "[!] FAILED: security gates"; rc=1; }; \
	if [ $$rc -ne 0 ]; then echo "[!] make test: one or more steps failed (all steps ran)"; fi; \
	exit $$rc

test-fixture-notice:
	@if [ -z "$$NEXUS_EVAL_TEST_WORKSPACE_ROOT" ] || [ -z "$$NEXUS_EVAL_TEST_RUNTIME_ROOT" ]; then \
	  echo "[i] NEXUS_EVAL_TEST_WORKSPACE_ROOT / NEXUS_EVAL_TEST_RUNTIME_ROOT are not set."; \
	  echo "[i] cli/test/eval_version_probe_storage.test.ts will FAIL without them, and cli/test/eval_integrity.test.ts"; \
	  echo "[i] runs its /dev/shm fallback branches instead of the capped-tmpfs ones. This is not a code defect."; \
	  echo "[i] Run 'make test-ci' to provision the same fixtures as CI (needs sudo)."; \
	fi

# Same gates as CI with the CI evaluator fixtures: mounts a capped tmpfs and runtime root, runs `make test`,
# then unmounts and removes only what it created. One-time host setup (not run here):
# scripts/install-evaluator-toolchains.sh, scripts/ensure-ci-bubblewrap.sh, scripts/ensure-ci-user-cgroups.sh.
test-ci:
	+@if [ -n "$(findstring n,$(firstword -$(MAKEFLAGS)))" ]; then echo 'dry run: would run scripts/with-ci-fixtures.sh -- make test'; else bash scripts/with-ci-fixtures.sh -- $(MAKE) test; fi

# Rebalance the CI shards from measured run times. Download the `test-shard-*` artifacts of a green CI run on the
# release branch into a directory (for example `gh run download <run-id> --pattern 'test-shard-*' --dir <dir>`),
# then run this and commit cli/scripts/test_durations.json. Details: cli/scripts/merge_test_durations.mjs.
test-durations-merge:
	@test -n "$(DIR)" || { echo "usage: make test-durations-merge DIR=<directory of downloaded test-shard artifacts>" >&2; exit 64; }
