name: Cross-runner RC reproducibility

on:
  # Weekly drift check against the newest published RC. Not a required check; a red run is the drift alert.
  schedule:
    - cron: "17 5 * * 1"
  workflow_dispatch:
    inputs:
      tag:
        description: Published RC tag with lock-pinned release tools (for example v1.1.0-rc.1)
        required: true
        type: string

permissions:
  contents: read

concurrency:
  group: rc-repro-${{ inputs.tag || 'scheduled' }}
  cancel-in-progress: false

jobs:
  resolve-tag:
    runs-on: ubuntu-22.04
    outputs:
      tag: ${{ steps.select.outputs.tag }}
      tag_sha: ${{ steps.resolve.outputs.tag_sha }}
      workflow_sha: ${{ steps.resolve.outputs.workflow_sha }}
    steps:
      - name: Require dispatch from main
        run: |
          if [[ "$GITHUB_REF" != "refs/heads/main" ]]; then
            echo "Dispatch this workflow from main so the checked workflow is the reviewed release version." >&2
            exit 1
          fi
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0
          persist-credentials: false
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 22.22.1
      - id: select
        name: Select the target RC tag
        env:
          GH_TOKEN: ${{ github.token }}
          INPUT_TAG: ${{ inputs.tag }}
        run: |
          tag="$INPUT_TAG"
          if [[ -z "$tag" ]]; then
            # Scheduled run: the newest published (non-draft) RC pre-release, newest first.
            tag="$(gh release list --repo "$GITHUB_REPOSITORY" --limit 100 --json tagName,isPrerelease,isDraft,createdAt \
              | jq -r '[.[] | select(.isPrerelease and (.isDraft | not) and (.tagName | test("^v[0-9]+\\.[0-9]+\\.[0-9]+-rc\\.[1-9][0-9]*$")))] | sort_by(.createdAt) | last | .tagName // empty')"
            if [[ -z "$tag" ]]; then
              echo "No published RC pre-release found to reproduce." >&2
              exit 1
            fi
          fi
          printf 'tag=%s\n' "$tag" >> "$GITHUB_OUTPUT"
          printf 'TARGET_TAG=%s\n' "$tag" >> "$GITHUB_ENV"
      - id: resolve
        name: Resolve published RC tag to an immutable commit
        run: |
          if [[ ! "$TARGET_TAG" =~ ^v[0-9]+\.[0-9]+\.[0-9]+-rc\.[1-9][0-9]*$ ]]; then
            echo "Expected a vX.Y.Z-rc.N tag; received an invalid tag." >&2
            exit 1
          fi
          git fetch origin main --no-tags
          git fetch origin "refs/tags/$TARGET_TAG:refs/tags/$TARGET_TAG"
          tag_sha="$(git rev-parse "$TARGET_TAG^{commit}")"
          git merge-base --is-ancestor "$tag_sha" origin/main
          git checkout --detach "$tag_sha"
          test "$(node -p 'require("./package.json").version')" = "${TARGET_TAG#v}"
          node scripts/sync-version.mjs --check --tag "$TARGET_TAG"
          test -f "docs/releases/$TARGET_TAG.md"
          if [[ ! -s scripts/release-tools/package.json || ! -s scripts/release-tools/package-lock.json ]] || \
             ! grep -Fq 'scripts/release-tools/package-lock.json' scripts/package-linux.sh || \
             ! grep -Fq 'check_deprecated_lock.mjs' scripts/package-linux.sh || \
             grep -Eq '(^|[[:space:]])npx([[:space:]]|$)' scripts/package-linux.sh scripts/generate_sbom.sh; then
            echo "The selected RC predates or bypasses the locked notices tool and lock deprecation gate; cross-runner reproduction requires an RC whose tag includes them." >&2
            exit 1
          fi
          printf 'tag_sha=%s\n' "$tag_sha" >> "$GITHUB_OUTPUT"
          printf 'workflow_sha=%s\n' "$GITHUB_WORKFLOW_SHA" >> "$GITHUB_OUTPUT"
      - name: Verify the public RC release is published
        env:
          GH_TOKEN: ${{ github.token }}
        run: |
          gh release view "$TARGET_TAG" --json isPrerelease,isDraft \
            | jq -e '.isPrerelease == true and .isDraft == false' >/dev/null

  build:
    needs: resolve-tag
    runs-on: ${{ matrix.runner }}
    timeout-minutes: 120
    strategy:
      fail-fast: false
      matrix:
        runner: [ubuntu-22.04, ubuntu-24.04]
    env:
      TARGET_TAG: ${{ needs.resolve-tag.outputs.tag }}
      EXPECTED_TAG_SHA: ${{ needs.resolve-tag.outputs.tag_sha }}
      EXPECTED_WORKFLOW_SHA: ${{ needs.resolve-tag.outputs.workflow_sha }}
      NEXUS_BUILD_CONTAINER_IMAGE: rust:1.95.0-bookworm@sha256:4c2fd73ef19c5ef9d54bee03b06b2839a392604fbfcd578ed948b71b37c1d7fb
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ needs.resolve-tag.outputs.tag_sha }}
          fetch-depth: 0
          persist-credentials: false
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 22.22.1
          cache: npm
          cache-dependency-path: cli/package-lock.json
      - name: Require the pinned release Node and npm versions
        run: |
          test "$(node --version)" = "v22.22.1"
          test "$(npm --version)" = "10.9.4"
      - name: Verify exact RC source
        run: |
name: Flake budget

# A test that needed a rerun to go green twice in the last 20 CI runs fails this job (PC-3). The JSON report is kept as an
# artifact. Weekly, and on demand; it only reads workflow history.
on:
  schedule:
    - cron: "17 6 * * 1"
  workflow_dispatch:

permissions:
  actions: read
  contents: read

jobs:
  report:
    runs-on: ubuntu-22.04
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 22.22.1
      - name: Build the flake report
        env:
          GH_TOKEN: ${{ github.token }}
        run: node scripts/flake_report.mjs --repo "$GITHUB_REPOSITORY" --workflow ci.yml --runs 20 --limit 2 --out flake-report.json
      - uses: actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9 # v7.0.2
        if: always()
        with:
          name: flake-report
          path: flake-report.json
          if-no-files-found: ignore
#!/usr/bin/env node
// PC-3 flake budget. A "rerun event" is a workflow run whose earlier attempt failed and whose final attempt passed:
// the same commit went red and then green with no change, which is what a flaky test looks like from outside.
// The report names the tests that failed in the earlier attempts (read from their job logs), counts per test how many of
// the last N runs needed such a rerun, and fails when one needed it LIMIT times. Pushing a fix is not a rerun and is not
// counted. Run weekly by .github/workflows/flake-report.yml; the JSON report is uploaded as an artifact.
//
//   node scripts/flake_report.mjs --repo owner/name [--workflow ci.yml] [--runs 20] [--limit 2] [--out flake-report.json]
//
// Needs the GitHub CLI authenticated (GH_TOKEN) with actions: read. Exit 0 within budget, 1 over budget, 2 on usage or
// API errors (a report that could not be built is never reported as "within budget").
import { execFile } from "node:child_process";
import fs from "node:fs";
import { promisify } from "node:util";
import { fileURLToPath } from "node:url";

const execFileAsync = promisify(execFile);

export const DEFAULT_RUNS = 20;
export const DEFAULT_LIMIT = 2;

/** Strips the Actions log timestamp prefix and ANSI colour codes from one line. */
const cleanLine = (line) => line.replace(/\u001b\[[0-9;]*[A-Za-z]/g, "").replace(/^\d{4}-\d{2}-\d{2}T[\d:.]+Z /, "");

/**
 * Names of the top-level tests listed under the runner's final "✖ failing tests:" summary. Nested subtests are indented
 * and the TAP noise of tests that run their own test runner is ignored.
 */
export function parseFailingTests(log) {
  const lines = String(log ?? "").split("\n").map(cleanLine);
  let start = -1;
  for (let i = 0; i < lines.length; i++) if (/^✖ failing tests:/.test(lines[i])) start = i;
  if (start < 0) return [];
  const names = new Set();
  for (const line of lines.slice(start + 1)) {
    const m = /^✖ (.+?) \(\d+(?:\.\d+)?ms\)\s*$/.exec(line);
    if (m) names.add(m[1]);
  }
  return [...names];
}

/**
 * @param {Array<{id:number, headSha:string, attempts:Array<{attempt:number, conclusion:string, failures:Array<{job:string, tests:string[]}>}>}>} runs
 */
export function analyze(runs, { limit = DEFAULT_LIMIT, window = runs.length, now = new Date() } = {}) {
  const events = [];
  let rerunRuns = 0;
  for (const run of runs) {
    const attempts = [...run.attempts].sort((a, b) => a.attempt - b.attempt);
    const last = attempts.at(-1);
    if (!last || last.conclusion !== "success") continue;
    const failed = attempts.filter((a) => a.attempt < last.attempt && a.conclusion !== "success");
    if (!failed.length) continue;
    rerunRuns++;
    for (const attempt of failed) {
      for (const failure of attempt.failures) {
        // A job that failed without a named test (setup, timeout, infrastructure) is recorded by job so it is not lost.
        const names = failure.tests.length ? failure.tests : [`job: ${failure.job} (no test named)`];
        for (const test of names) events.push({ runId: run.id, sha: run.headSha, attempt: attempt.attempt, job: failure.job, test });
      }
    }
  }
  const byTest = new Map();
  for (const e of events) {
    const entry = byTest.get(e.test) ?? { test: e.test, runs: new Set() };
    entry.runs.add(e.runId);
    byTest.set(e.test, entry);
  }
  const ranked = [...byTest.values()].map((e) => ({ test: e.test, runs: e.runs.size, runIds: [...e.runs].sort((a, b) => a - b) })).sort((a, b) => b.runs - a.runs || a.test.localeCompare(b.test));
  return {
    schemaVersion: 1,
    generatedAt: now.toISOString(),
    runsExamined: runs.length,
    window,
    runsNeedingRerun: rerunRuns,
    events,
    byTest: ranked,
    budget: { limit, exceeded: ranked.filter((e) => e.runs >= limit).map((e) => e.test) },
  };
}

/** One Markdown table cell: backslashes first (so an escape we add cannot be cancelled by one already in the text), then the column separator and line breaks. */
const escapeCell = (text) => String(text).replace(/\\/g, "\\\\").replace(/\|/g, "\\|").replace(/[\r\n]+/g, " ");

export function renderMarkdown(report) {
  const lines = [
    "## Flake budget",
    "",
    `${report.runsExamined} runs examined, ${report.runsNeedingRerun} needed a rerun to go green. Budget: a test may need a rerun in fewer than ${report.budget.limit} of ${report.window} runs.`,
    "",
  ];
  if (!report.byTest.length) lines.push("No rerun events.");
  else {
    lines.push("| Test | Runs needing a rerun | Status |", "|---|---|---|");
    for (const e of report.byTest) lines.push(`| ${escapeCell(e.test)} | ${e.runs} | ${report.budget.exceeded.includes(e.test) ? "**over budget**" : "within budget"} |`);
  }
  return `${lines.join("\n")}\n`;
}

/** The only place that talks to GitHub; `gh` is injectable so the logic above is testable offline. */
async function defaultGh(args) {
  const { stdout } = await execFileAsync("gh", args, { maxBuffer: 256 * 1024 * 1024 });
  return stdout;
}

export async function fetchRuns({ repo, workflow, runs, gh = defaultGh }) {
  const api = async (path, extra = []) => gh(["api", ...extra, path]);
  const list = JSON.parse(await api(`repos/${repo}/actions/workflows/${workflow}/runs?per_page=${runs}&status=completed`));
  const out = [];
  for (const run of list.workflow_runs ?? []) {
    const attempts = [];
    for (let n = 1; n <= (run.run_attempt ?? 1); n++) {
      const jobs = JSON.parse(await api(`repos/${repo}/actions/runs/${run.id}/attempts/${n}/jobs?per_page=100`)).jobs ?? [];
      const failed = jobs.filter((j) => j.conclusion && j.conclusion !== "success" && j.conclusion !== "skipped");
      const failures = [];
      // Logs are only worth reading for an attempt that a later one superseded.
      const superseded = n < (run.run_attempt ?? 1);
      for (const job of failed) {
        const tests = superseded ? parseFailingTests(await api(`repos/${repo}/actions/jobs/${job.id}/logs`, ["--allow-escape-sequences"]).catch(() => "")) : [];
        failures.push({ job: job.name, tests });
      }
      attempts.push({ attempt: n, conclusion: n === (run.run_attempt ?? 1) ? run.conclusion : failed.length ? "failure" : "success", failures });
    }
    out.push({ id: run.id, headSha: run.head_sha, attempts });
  }
  return out;
}

function parseArgs(argv) {
  const opts = { workflow: "ci.yml", runs: DEFAULT_RUNS, limit: DEFAULT_LIMIT, out: "flake-report.json" };
  for (let i = 0; i < argv.length; i++) {
    const key = argv[i];
    const value = argv[++i];
    if (!["--repo", "--workflow", "--runs", "--limit", "--out"].includes(key) || value === undefined) throw new Error(`usage: flake_report.mjs --repo owner/name [--workflow ci.yml] [--runs ${DEFAULT_RUNS}] [--limit ${DEFAULT_LIMIT}] [--out file]`);
    opts[key.slice(2)] = key === "--runs" || key === "--limit" ? Number(value) : value;
  }
  if (!/^[\w.-]+\/[\w.-]+$/.test(opts.repo ?? "")) throw new Error("--repo owner/name is required");
  if (!/^[\w.-]+\.ya?ml$/.test(opts.workflow)) throw new Error("--workflow must be a workflow file name");
  for (const k of ["runs", "limit"]) if (!Number.isInteger(opts[k]) || opts[k] < 1 || opts[k] > 100) throw new Error(`--${k} must be an integer from 1 to 100`);
  return opts;
}

async function main(argv) {
  let opts;
  try {
    opts = parseArgs(argv);
  } catch (error) {
    console.error(error.message);
    return 2;
  }
  let report;
  try {
    report = analyze(await fetchRuns({ repo: opts.repo, workflow: opts.workflow, runs: opts.runs }), { limit: opts.limit, window: opts.runs });
  } catch (error) {
    console.error(`flake report could not be built: ${String(error?.message ?? error).split("\n")[0]}`);
    return 2;
  }
  fs.writeFileSync(opts.out, `${JSON.stringify(report, null, 2)}\n`);
  const markdown = renderMarkdown(report);
  if (process.env.GITHUB_STEP_SUMMARY) fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, markdown);
  process.stdout.write(markdown);
  if (report.budget.exceeded.length) {
    console.error(`flake budget exceeded by: ${report.budget.exceeded.join("; ")}`);
    return 1;
  }
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) process.exitCode = await main(process.argv.slice(2));
/** PC-3: the flake budget. The log parser is checked against a trimmed real CI failure summary; the rest runs offline with an injected `gh`. */
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
// @ts-expect-error plain ESM script, no declarations
import { analyze, fetchRuns, parseFailingTests, renderMarkdown } from "../../scripts/flake_report.mjs";

const here = path.dirname(fileURLToPath(import.meta.url));
const SCRIPT = path.resolve(here, "../../scripts/flake_report.mjs");

test("the failing-test summary of a real CI log yields the top-level test names only", () => {
  const log = fs.readFileSync(path.join(here, "fixtures/flake/ci-failing-tests.txt"), "utf8");
  assert.deepEqual(parseFailingTests(log), [
    "a subcommand receives its own --provider and -m",
    "providers list preserves safe unknown-provider diagnostics and redacts credential-shaped IDs",
  ]);
});

test("the parser ignores progress lines, takes the last summary, strips colour codes, and returns nothing without one", () => {
  assert.deepEqual(parseFailingTests(""), []);
  assert.deepEqual(parseFailingTests("✖ Working: edit_file\n✖ Tool Error:\nℹ fail 0\n"), []);
  const coloured = "2026-11-17T01:00:00.0000000Z \u001b[31m✖ failing tests:\u001b[39m\n2026-11-17T01:00:00.0000001Z \u001b[31m✖ real one (12.5ms)\u001b[39m\n  ✖ nested subtest (1ms)\n✖ Working: noise\n";
  assert.deepEqual(parseFailingTests(coloured), ["real one"]);
  assert.deepEqual(parseFailingTests("✖ failing tests:\n✖ early (1ms)\n✖ failing tests:\n✖ late (1ms)\n"), ["late"]);
});

const run = (id: number, attempts: Array<[number, string, Array<[string, string[]]>?]>) => ({
  id,
  headSha: `sha${id}`,
  attempts: attempts.map(([attempt, conclusion, failures = []]) => ({ attempt, conclusion, failures: failures.map(([job, tests]) => ({ job, tests })) })),
});

test("a rerun event is a run that failed and then passed unchanged; fixes pushed as new runs and still-red runs are not counted", () => {
  const report = analyze([
    run(1, [[1, "failure", [["test-matrix (22)", ["flaky A"]]]], [2, "success"]]),
    run(2, [[1, "success"]]),
    run(3, [[1, "failure", [["linux-x86_64", ["real bug"]]]]]),
    run(4, [[1, "failure", [["linux-x86_64", ["still broken"]]]], [2, "failure", [["linux-x86_64", ["still broken"]]]]]),
  ], { limit: 2, window: 20, now: new Date("2026-11-17T00:00:00Z") });
  assert.equal(report.runsExamined, 4);
  assert.equal(report.runsNeedingRerun, 1);
  assert.deepEqual(report.byTest, [{ test: "flaky A", runs: 1, runIds: [1] }]);
  assert.deepEqual(report.budget.exceeded, []);
  assert.equal(report.generatedAt, "2026-11-17T00:00:00.000Z");
});

test("the budget fails a test that needed a rerun in two runs, counting a run once however often it failed", () => {
  const report = analyze([
    run(10, [[1, "failure", [["a", ["flaky A", "flaky B"]], ["b", ["flaky A"]]]], [2, "failure", [["a", ["flaky A"]]]], [3, "success"]]),
    run(11, [[1, "failure", [["a", ["flaky A"]]]], [2, "success"]]),
    run(12, [[1, "failure", [["a", ["flaky B"]]]], [2, "success"]]),
  ], { limit: 3, window: 20 });
  assert.deepEqual(report.byTest.map((e: any) => [e.test, e.runs]), [["flaky A", 2], ["flaky B", 2]]);
  assert.deepEqual(report.budget.exceeded, []);
  const strict = analyze([
    run(10, [[1, "failure", [["a", ["flaky A"]]]], [2, "success"]]),
    run(11, [[1, "failure", [["a", ["flaky A"]]]], [2, "success"]]),
  ], { limit: 2, window: 20 });
  assert.deepEqual(strict.budget.exceeded, ["flaky A"]);
  assert.match(renderMarkdown(strict), /\| flaky A \| 2 \| \*\*over budget\*\* \|/);
});

test("a job that failed without a named test is still recorded, by job", () => {
  const report = analyze([run(5, [[1, "failure", [["linux-x86_64", []]]], [2, "success"]])]);
  assert.deepEqual(report.byTest.map((e: any) => e.test), ["job: linux-x86_64 (no test named)"]);
});

test("fetchRuns reads superseded attempts' logs through the API and nothing else", async () => {
  const calls: string[] = [];
  const log = fs.readFileSync(path.join(here, "fixtures/flake/ci-failing-tests.txt"), "utf8");
  const gh = async (args: string[]) => {
    const target = args.at(-1)!;
    calls.push(target);
    if (target.includes("/workflows/ci.yml/runs")) return JSON.stringify({ workflow_runs: [{ id: 7, head_sha: "abc", run_attempt: 2, conclusion: "success" }, { id: 8, head_sha: "def", run_attempt: 1, conclusion: "success" }] });
    if (target.includes("/runs/7/attempts/1/jobs")) return JSON.stringify({ jobs: [{ id: 70, name: "test-matrix (22)", conclusion: "failure" }, { id: 71, name: "linux-x86_64", conclusion: "success" }] });
    if (target.includes("/runs/7/attempts/2/jobs")) return JSON.stringify({ jobs: [{ id: 72, name: "test-matrix (22)", conclusion: "success" }] });
    if (target.includes("/runs/8/attempts/1/jobs")) return JSON.stringify({ jobs: [{ id: 80, name: "test-matrix (22)", conclusion: "success" }] });
    if (target.endsWith("/jobs/70/logs")) return log;
    throw new Error(`unexpected request ${target}`);
  };
  const runs = await fetchRuns({ repo: "o/r", workflow: "ci.yml", runs: 20, gh });
  assert.deepEqual(calls.filter((c) => c.includes("/logs")), ["repos/o/r/actions/jobs/70/logs"], "only the superseded failed job's log is read");
  const report = analyze(runs, { limit: 2, window: 20 });
  assert.equal(report.runsNeedingRerun, 1);
  assert.equal(report.byTest.length, 2);
  assert.equal(report.events[0].job, "test-matrix (22)");
});

test("the command refuses bad arguments with exit 2 and never reports a budget it could not compute", () => {
  const bad = spawnSync(process.execPath, [SCRIPT, "--repo", "not a repo"], { encoding: "utf8" });
  assert.equal(bad.status, 2);
  assert.match(bad.stderr, /--repo owner\/name is required/);
  const unknown = spawnSync(process.execPath, [SCRIPT, "--bogus", "x"], { encoding: "utf8" });
  assert.equal(unknown.status, 2);
  const range = spawnSync(process.execPath, [SCRIPT, "--repo", "o/r", "--runs", "500"], { encoding: "utf8" });
  assert.equal(range.status, 2);
  assert.match(range.stderr, /--runs must be an integer from 1 to 100/);
});

test("a table cell cannot be broken out of: backslashes, pipes and line breaks in a test name are neutralised", () => {
  const evil = "ends with backslash \\";
  const report = analyze([
    run(1, [[1, "failure", [["a", [evil, "has | pipe", "two\nlines"]]]], [2, "success"]]),
    run(2, [[1, "failure", [["a", [evil, "has | pipe", "two\nlines"]]]], [2, "success"]]),
  ], { limit: 2, window: 20 });
  const rows = renderMarkdown(report).split("\n").filter((l: string) => l.startsWith("| ") && !l.startsWith("| Test") && !l.startsWith("|---"));
  assert.equal(rows.length, 3, "one row per test, whatever the names contain");
  for (const row of rows) {
    // After removing escaped characters, a row has exactly its three cells: four unescaped separators.
    assert.equal((row.replace(/\\\\|\\\|/g, "").match(/\|/g) ?? []).length, 4, row);
  }
  assert.ok(rows.some((r: string) => r.includes("ends with backslash \\\\ |")), "the trailing backslash is doubled, so it cannot cancel the cell's closing pipe");
  assert.ok(rows.some((r: string) => r.includes("has \\| pipe")));
  assert.ok(rows.some((r: string) => r.includes("two lines")));
});

toolUseResult.stdout:
name: Cross-runner RC reproducibility

on:
  # Weekly drift check against the newest published RC. Not a required check; a red run is the drift alert.
  schedule:
    - cron: "17 5 * * 1"
  workflow_dispatch:
    inputs:
      tag:
        description: Published RC tag with lock-pinned release tools (for example v1.1.0-rc.1)
        required: true
        type: string

permissions:
  contents: read

concurrency:
  group: rc-repro-${{ inputs.tag || 'scheduled' }}
  cancel-in-progress: false

jobs:
  resolve-tag:
    runs-on: ubuntu-22.04
    outputs:
      tag: ${{ steps.select.outputs.tag }}
      tag_sha: ${{ steps.resolve.outputs.tag_sha }}
      workflow_sha: ${{ steps.resolve.outputs.workflow_sha }}
    steps:
      - name: Require dispatch from main
        run: |
          if [[ "$GITHUB_REF" != "refs/heads/main" ]]; then
            echo "Dispatch this workflow from main so the checked workflow is the reviewed release version." >&2
            exit 1
          fi
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0
          persist-credentials: false
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 22.22.1
      - id: select
        name: Select the target RC tag
        env:
          GH_TOKEN: ${{ github.token }}
          INPUT_TAG: ${{ inputs.tag }}
        run: |
          tag="$INPUT_TAG"
          if [[ -z "$tag" ]]; then
            # Scheduled run: the newest published (non-draft) RC pre-release, newest first.
            tag="$(gh release list --repo "$GITHUB_REPOSITORY" --limit 100 --json tagName,isPrerelease,isDraft,createdAt \
              | jq -r '[.[] | select(.isPrerelease and (.isDraft | not) and (.tagName | test("^v[0-9]+\\.[0-9]+\\.[0-9]+-rc\\.[1-9][0-9]*$")))] | sort_by(.createdAt) | last | .tagName // empty')"
            if [[ -z "$tag" ]]; then
              echo "No published RC pre-release found to reproduce." >&2
              exit 1
            fi
          fi
          printf 'tag=%s\n' "$tag" >> "$GITHUB_OUTPUT"
          printf 'TARGET_TAG=%s\n' "$tag" >> "$GITHUB_ENV"
      - id: resolve
        name: Resolve published RC tag to an immutable commit
        run: |
          if [[ ! "$TARGET_TAG" =~ ^v[0-9]+\.[0-9]+\.[0-9]+-rc\.[1-9][0-9]*$ ]]; then
            echo "Expected a vX.Y.Z-rc.N tag; received an invalid tag." >&2
            exit 1
          fi
          git fetch origin main --no-tags
          git fetch origin "refs/tags/$TARGET_TAG:refs/tags/$TARGET_TAG"
          tag_sha="$(git rev-parse "$TARGET_TAG^{commit}")"
          git merge-base --is-ancestor "$tag_sha" origin/main
          git checkout --detach "$tag_sha"
          test "$(node -p 'require("./package.json").version')" = "${TARGET_TAG#v}"
          node scripts/sync-version.mjs --check --tag "$TARGET_TAG"
          test -f "docs/releases/$TARGET_TAG.md"
          if [[ ! -s scripts/release-tools/package.json || ! -s scripts/release-tools/package-lock.json ]] || \
             ! grep -Fq 'scripts/release-tools/package-lock.json' scripts/package-linux.sh || \
             ! grep -Fq 'check_deprecated_lock.mjs' scripts/package-linux.sh || \
             grep -Eq '(^|[[:space:]])npx([[:space:]]|$)' scripts/package-linux.sh scripts/generate_sbom.sh; then
            echo "The selected RC predates or bypasses the locked notices tool and lock deprecation gate; cross-runner reproduction requires an RC whose tag includes them." >&2
            exit 1
          fi
          printf 'tag_sha=%s\n' "$tag_sha" >> "$GITHUB_OUTPUT"
          printf 'workflow_sha=%s\n' "$GITHUB_WORKFLOW_SHA" >> "$GITHUB_OUTPUT"
      - name: Verify the public RC release is published
        env:
          GH_TOKEN: ${{ github.token }}
        run: |
          gh release view "$TARGET_TAG" --json isPrerelease,isDraft \
            | jq -e '.isPrerelease == true and .isDraft == false' >/dev/null

  build:
    needs: resolve-tag
    runs-on: ${{ matrix.runner }}
    timeout-minutes: 120
    strategy:
      fail-fast: false
      matrix:
        runner: [ubuntu-22.04, ubuntu-24.04]
    env:
      TARGET_TAG: ${{ needs.resolve-tag.outputs.tag }}
      EXPECTED_TAG_SHA: ${{ needs.resolve-tag.outputs.tag_sha }}
      EXPECTED_WORKFLOW_SHA: ${{ needs.resolve-tag.outputs.workflow_sha }}
      NEXUS_BUILD_CONTAINER_IMAGE: rust:1.95.0-bookworm@sha256:4c2fd73ef19c5ef9d54bee03b06b2839a392604fbfcd578ed948b71b37c1d7fb
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ needs.resolve-tag.outputs.tag_sha }}
          fetch-depth: 0
          persist-credentials: false
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 22.22.1
          cache: npm
          cache-dependency-path: cli/package-lock.json
      - name: Require the pinned release Node and npm versions
        run: |
          test "$(node --version)" = "v22.22.1"
          test "$(npm --version)" = "10.9.4"
      - name: Verify exact RC source
        run: |
name: Flake budget

# A test that needed a rerun to go green twice in the last 20 CI runs fails this job (PC-3). The JSON report is kept as an
# artifact. Weekly, and on demand; it only reads workflow history.
on:
  schedule:
    - cron: "17 6 * * 1"
  workflow_dispatch:

permissions:
  actions: read
  contents: read

jobs:
  report:
    runs-on: ubuntu-22.04
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 22.22.1
      - name: Build the flake report
        env:
          GH_TOKEN: ${{ github.token }}
        run: node scripts/flake_report.mjs --repo "$GITHUB_REPOSITORY" --workflow ci.yml --runs 20 --limit 2 --out flake-report.json
      - uses: actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9 # v7.0.2
        if: always()
        with:
          name: flake-report
          path: flake-report.json
          if-no-files-found: ignore
#!/usr/bin/env node
// PC-3 flake budget. A "rerun event" is a workflow run whose earlier attempt failed and whose final attempt passed:
// the same commit went red and then green with no change, which is what a flaky test looks like from outside.
// The report names the tests that failed in the earlier attempts (read from their job logs), counts per test how many of
// the last N runs needed such a rerun, and fails when one needed it LIMIT times. Pushing a fix is not a rerun and is not
// counted. Run weekly by .github/workflows/flake-report.yml; the JSON report is uploaded as an artifact.
//
//   node scripts/flake_report.mjs --repo owner/name [--workflow ci.yml] [--runs 20] [--limit 2] [--out flake-report.json]
//
// Needs the GitHub CLI authenticated (GH_TOKEN) with actions: read. Exit 0 within budget, 1 over budget, 2 on usage or
// API errors (a report that could not be built is never reported as "within budget").
import { execFile } from "node:child_process";
import fs from "node:fs";
import { promisify } from "node:util";
import { fileURLToPath } from "node:url";

const execFileAsync = promisify(execFile);

export const DEFAULT_RUNS = 20;
export const DEFAULT_LIMIT = 2;

/** Strips the Actions log timestamp prefix and ANSI colour codes from one line. */
const cleanLine = (line) => line.replace(/\u001b\[[0-9;]*[A-Za-z]/g, "").replace(/^\d{4}-\d{2}-\d{2}T[\d:.]+Z /, "");

/**
 * Names of the top-level tests listed under the runner's final "✖ failing tests:" summary. Nested subtests are indented
 * and the TAP noise of tests that run their own test runner is ignored.
 */
export function parseFailingTests(log) {
  const lines = String(log ?? "").split("\n").map(cleanLine);
  let start = -1;
  for (let i = 0; i < lines.length; i++) if (/^✖ failing tests:/.test(lines[i])) start = i;
  if (start < 0) return [];
  const names = new Set();
  for (const line of lines.slice(start + 1)) {
    const m = /^✖ (.+?) \(\d+(?:\.\d+)?ms\)\s*$/.exec(line);
    if (m) names.add(m[1]);
  }
  return [...names];
}

/**
 * @param {Array<{id:number, headSha:string, attempts:Array<{attempt:number, conclusion:string, failures:Array<{job:string, tests:string[]}>}>}>} runs
 */
export function analyze(runs, { limit = DEFAULT_LIMIT, window = runs.length, now = new Date() } = {}) {
  const events = [];
  let rerunRuns = 0;
  for (const run of runs) {
    const attempts = [...run.attempts].sort((a, b) => a.attempt - b.attempt);
    const last = attempts.at(-1);
    if (!last || last.conclusion !== "success") continue;
    const failed = attempts.filter((a) => a.attempt < last.attempt && a.conclusion !== "success");
    if (!failed.length) continue;
    rerunRuns++;
    for (const attempt of failed) {
      for (const failure of attempt.failures) {
        // A job that failed without a named test (setup, timeout, infrastructure) is recorded by job so it is not lost.
        const names = failure.tests.length ? failure.tests : [`job: ${failure.job} (no test named)`];
        for (const test of names) events.push({ runId: run.id, sha: run.headSha, attempt: attempt.attempt, job: failure.job, test });
      }
    }
  }
  const byTest = new Map();
  for (const e of events) {
    const entry = byTest.get(e.test) ?? { test: e.test, runs: new Set() };
    entry.runs.add(e.runId);
    byTest.set(e.test, entry);
  }
  const ranked = [...byTest.values()].map((e) => ({ test: e.test, runs: e.runs.size, runIds: [...e.runs].sort((a, b) => a - b) })).sort((a, b) => b.runs - a.runs || a.test.localeCompare(b.test));
  return {
    schemaVersion: 1,
    generatedAt: now.toISOString(),
    runsExamined: runs.length,
    window,
    runsNeedingRerun: rerunRuns,
    events,
    byTest: ranked,
    budget: { limit, exceeded: ranked.filter((e) => e.runs >= limit).map((e) => e.test) },
  };
}

/** One Markdown table cell: backslashes first (so an escape we add cannot be cancelled by one already in the text), then the column separator and line breaks. */
const escapeCell = (text) => String(text).replace(/\\/g, "\\\\").replace(/\|/g, "\\|").replace(/[\r\n]+/g, " ");

export function renderMarkdown(report) {
  const lines = [
    "## Flake budget",
    "",
    `${report.runsExamined} runs examined, ${report.runsNeedingRerun} needed a rerun to go green. Budget: a test may need a rerun in fewer than ${report.budget.limit} of ${report.window} runs.`,
    "",
  ];
  if (!report.byTest.length) lines.push("No rerun events.");
  else {
    lines.push("| Test | Runs needing a rerun | Status |", "|---|---|---|");
    for (const e of report.byTest) lines.push(`| ${escapeCell(e.test)} | ${e.runs} | ${report.budget.exceeded.includes(e.test) ? "**over budget**" : "within budget"} |`);
  }
  return `${lines.join("\n")}\n`;
}

/** The only place that talks to GitHub; `gh` is injectable so the logic above is testable offline. */
async function defaultGh(args) {
  const { stdout } = await execFileAsync("gh", args, { maxBuffer: 256 * 1024 * 1024 });
  return stdout;
}

export async function fetchRuns({ repo, workflow, runs, gh = defaultGh }) {
  const api = async (path, extra = []) => gh(["api", ...extra, path]);
  const list = JSON.parse(await api(`repos/${repo}/actions/workflows/${workflow}/runs?per_page=${runs}&status=completed`));
  const out = [];
  for (const run of list.workflow_runs ?? []) {
    const attempts = [];
    for (let n = 1; n <= (run.run_attempt ?? 1); n++) {
      const jobs = JSON.parse(await api(`repos/${repo}/actions/runs/${run.id}/attempts/${n}/jobs?per_page=100`)).jobs ?? [];
      const failed = jobs.filter((j) => j.conclusion && j.conclusion !== "success" && j.conclusion !== "skipped");
      const failures = [];
      // Logs are only worth reading for an attempt that a later one superseded.
      const superseded = n < (run.run_attempt ?? 1);
      for (const job of failed) {
        const tests = superseded ? parseFailingTests(await api(`repos/${repo}/actions/jobs/${job.id}/logs`, ["--allow-escape-sequences"]).catch(() => "")) : [];
        failures.push({ job: job.name, tests });
      }
      attempts.push({ attempt: n, conclusion: n === (run.run_attempt ?? 1) ? run.conclusion : failed.length ? "failure" : "success", failures });
    }
    out.push({ id: run.id, headSha: run.head_sha, attempts });
  }
  return out;
}

function parseArgs(argv) {
  const opts = { workflow: "ci.yml", runs: DEFAULT_RUNS, limit: DEFAULT_LIMIT, out: "flake-report.json" };
  for (let i = 0; i < argv.length; i++) {
    const key = argv[i];
    const value = argv[++i];
    if (!["--repo", "--workflow", "--runs", "--limit", "--out"].includes(key) || value === undefined) throw new Error(`usage: flake_report.mjs --repo owner/name [--workflow ci.yml] [--runs ${DEFAULT_RUNS}] [--limit ${DEFAULT_LIMIT}] [--out file]`);
    opts[key.slice(2)] = key === "--runs" || key === "--limit" ? Number(value) : value;
  }
  if (!/^[\w.-]+\/[\w.-]+$/.test(opts.repo ?? "")) throw new Error("--repo owner/name is required");
  if (!/^[\w.-]+\.ya?ml$/.test(opts.workflow)) throw new Error("--workflow must be a workflow file name");
  for (const k of ["runs", "limit"]) if (!Number.isInteger(opts[k]) || opts[k] < 1 || opts[k] > 100) throw new Error(`--${k} must be an integer from 1 to 100`);
  return opts;
}

async function main(argv) {
  let opts;
  try {
    opts = parseArgs(argv);
  } catch (error) {
    console.error(error.message);
    return 2;
  }
  let report;
  try {
    report = analyze(await fetchRuns({ repo: opts.repo, workflow: opts.workflow, runs: opts.runs }), { limit: opts.limit, window: opts.runs });
  } catch (error) {
    console.error(`flake report could not be built: ${String(error?.message ?? error).split("\n")[0]}`);
    return 2;
  }
  fs.writeFileSync(opts.out, `${JSON.stringify(report, null, 2)}\n`);
  const markdown = renderMarkdown(report);
  if (process.env.GITHUB_STEP_SUMMARY) fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, markdown);
  process.stdout.write(markdown);
  if (report.budget.exceeded.length) {
    console.error(`flake budget exceeded by: ${report.budget.exceeded.join("; ")}`);
    return 1;
  }
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) process.exitCode = await main(process.argv.slice(2));
/** PC-3: the flake budget. The log parser is checked against a trimmed real CI failure summary; the rest runs offline with an injected `gh`. */
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
// @ts-expect-error plain ESM script, no declarations
import { analyze, fetchRuns, parseFailingTests, renderMarkdown } from "../../scripts/flake_report.mjs";

const here = path.dirname(fileURLToPath(import.meta.url));
const SCRIPT = path.resolve(here, "../../scripts/flake_report.mjs");

test("the failing-test summary of a real CI log yields the top-level test names only", () => {
  const log = fs.readFileSync(path.join(here, "fixtures/flake/ci-failing-tests.txt"), "utf8");
  assert.deepEqual(parseFailingTests(log), [
    "a subcommand receives its own --provider and -m",
    "providers list preserves safe unknown-provider diagnostics and redacts credential-shaped IDs",
  ]);
});

test("the parser ignores progress lines, takes the last summary, strips colour codes, and returns nothing without one", () => {
  assert.deepEqual(parseFailingTests(""), []);
  assert.deepEqual(parseFailingTests("✖ Working: edit_file\n✖ Tool Error:\nℹ fail 0\n"), []);
  const coloured = "2026-11-17T01:00:00.0000000Z \u001b[31m✖ failing tests:\u001b[39m\n2026-11-17T01:00:00.0000001Z \u001b[31m✖ real one (12.5ms)\u001b[39m\n  ✖ nested subtest (1ms)\n✖ Working: noise\n";
  assert.deepEqual(parseFailingTests(coloured), ["real one"]);
  assert.deepEqual(parseFailingTests("✖ failing tests:\n✖ early (1ms)\n✖ failing tests:\n✖ late (1ms)\n"), ["late"]);
});

const run = (id: number, attempts: Array<[number, string, Array<[string, string[]]>?]>) => ({
  id,
  headSha: `sha${id}`,
  attempts: attempts.map(([attempt, conclusion, failures = []]) => ({ attempt, conclusion, failures: failures.map(([job, tests]) => ({ job, tests })) })),
});

test("a rerun event is a run that failed and then passed unchanged; fixes pushed as new runs and still-red runs are not counted", () => {
  const report = analyze([
    run(1, [[1, "failure", [["test-matrix (22)", ["flaky A"]]]], [2, "success"]]),
    run(2, [[1, "success"]]),
    run(3, [[1, "failure", [["linux-x86_64", ["real bug"]]]]]),
    run(4, [[1, "failure", [["linux-x86_64", ["still broken"]]]], [2, "failure", [["linux-x86_64", ["still broken"]]]]]),
  ], { limit: 2, window: 20, now: new Date("2026-11-17T00:00:00Z") });
  assert.equal(report.runsExamined, 4);
  assert.equal(report.runsNeedingRerun, 1);
  assert.deepEqual(report.byTest, [{ test: "flaky A", runs: 1, runIds: [1] }]);
  assert.deepEqual(report.budget.exceeded, []);
  assert.equal(report.generatedAt, "2026-11-17T00:00:00.000Z");
});

test("the budget fails a test that needed a rerun in two runs, counting a run once however often it failed", () => {
  const report = analyze([
    run(10, [[1, "failure", [["a", ["flaky A", "flaky B"]], ["b", ["flaky A"]]]], [2, "failure", [["a", ["flaky A"]]]], [3, "success"]]),
    run(11, [[1, "failure", [["a", ["flaky A"]]]], [2, "success"]]),
    run(12, [[1, "failure", [["a", ["flaky B"]]]], [2, "success"]]),
  ], { limit: 3, window: 20 });
  assert.deepEqual(report.byTest.map((e: any) => [e.test, e.runs]), [["flaky A", 2], ["flaky B", 2]]);
  assert.deepEqual(report.budget.exceeded, []);
  const strict = analyze([
    run(10, [[1, "failure", [["a", ["flaky A"]]]], [2, "success"]]),
    run(11, [[1, "failure", [["a", ["flaky A"]]]], [2, "success"]]),
  ], { limit: 2, window: 20 });
  assert.deepEqual(strict.budget.exceeded, ["flaky A"]);
  assert.match(renderMarkdown(strict), /\| flaky A \| 2 \| \*\*over budget\*\* \|/);
});

test("a job that failed without a named test is still recorded, by job", () => {
  const report = analyze([run(5, [[1, "failure", [["linux-x86_64", []]]], [2, "success"]])]);
  assert.deepEqual(report.byTest.map((e: any) => e.test), ["job: linux-x86_64 (no test named)"]);
});

test("fetchRuns reads superseded attempts' logs through the API and nothing else", async () => {
  const calls: string[] = [];
  const log = fs.readFileSync(path.join(here, "fixtures/flake/ci-failing-tests.txt"), "utf8");
  const gh = async (args: string[]) => {
    const target = args.at(-1)!;
    calls.push(target);
    if (target.includes("/workflows/ci.yml/runs")) return JSON.stringify({ workflow_runs: [{ id: 7, head_sha: "abc", run_attempt: 2, conclusion: "success" }, { id: 8, head_sha: "def", run_attempt: 1, conclusion: "success" }] });
    if (target.includes("/runs/7/attempts/1/jobs")) return JSON.stringify({ jobs: [{ id: 70, name: "test-matrix (22)", conclusion: "failure" }, { id: 71, name: "linux-x86_64", conclusion: "success" }] });
    if (target.includes("/runs/7/attempts/2/jobs")) return JSON.stringify({ jobs: [{ id: 72, name: "test-matrix (22)", conclusion: "success" }] });
    if (target.includes("/runs/8/attempts/1/jobs")) return JSON.stringify({ jobs: [{ id: 80, name: "test-matrix (22)", conclusion: "success" }] });
    if (target.endsWith("/jobs/70/logs")) return log;
    throw new Error(`unexpected request ${target}`);
  };
  const runs = await fetchRuns({ repo: "o/r", workflow: "ci.yml", runs: 20, gh });
  assert.deepEqual(calls.filter((c) => c.includes("/logs")), ["repos/o/r/actions/jobs/70/logs"], "only the superseded failed job's log is read");
  const report = analyze(runs, { limit: 2, window: 20 });
  assert.equal(report.runsNeedingRerun, 1);
  assert.equal(report.byTest.length, 2);
  assert.equal(report.events[0].job, "test-matrix (22)");
});

test("the command refuses bad arguments with exit 2 and never reports a budget it could not compute", () => {
  const bad = spawnSync(process.execPath, [SCRIPT, "--repo", "not a repo"], { encoding: "utf8" });
  assert.equal(bad.status, 2);
  assert.match(bad.stderr, /--repo owner\/name is required/);
  const unknown = spawnSync(process.execPath, [SCRIPT, "--bogus", "x"], { encoding: "utf8" });
  assert.equal(unknown.status, 2);
  const range = spawnSync(process.execPath, [SCRIPT, "--repo", "o/r", "--runs", "500"], { encoding: "utf8" });
  assert.equal(range.status, 2);
  assert.match(range.stderr, /--runs must be an integer from 1 to 100/);
});

test("a table cell cannot be broken out of: backslashes, pipes and line breaks in a test name are neutralised", () => {
  const evil = "ends with backslash \\";
  const report = analyze([
    run(1, [[1, "failure", [["a", [evil, "has | pipe", "two\nlines"]]]], [2, "success"]]),
    run(2, [[1, "failure", [["a", [evil, "has | pipe", "two\nlines"]]]], [2, "success"]]),
  ], { limit: 2, window: 20 });
  const rows = renderMarkdown(report).split("\n").filter((l: string) => l.startsWith("| ") && !l.startsWith("| Test") && !l.startsWith("|---"));
  assert.equal(rows.length, 3, "one row per test, whatever the names contain");
  for (const row of rows) {
    // After removing escaped characters, a row has exactly its three cells: four unescaped separators.
    assert.equal((row.replace(/\\\\|\\\|/g, "").match(/\|/g) ?? []).length, 4, row);
  }
  assert.ok(rows.some((r: string) => r.includes("ends with backslash \\\\ |")), "the trailing backslash is doubled, so it cannot cancel the cell's closing pipe");
  assert.ok(rows.some((r: string) => r.includes("has \\| pipe")));
  assert.ok(rows.some((r: string) => r.includes("two lines")));
});

